// Bit-exact parity test: C++ engine output vs vectors generated by the real
// Python ops (tools/gen_vectors.py). Compares raw bytes, not tolerance.
#include "engine.hpp"

#include <mlx/mlx.h>

#include <cassert>
#include <cstdint>
#include <cstdio>
#include <string>

namespace mx = mlx::core;
using namespace veystrix::engine;

// Compare arrays bit-for-bit by viewing their bytes as uint32.
static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape()) return false;
  mx::array av = mx::astype(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::astype(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return false;
  return true;
}

int main(int argc, char** argv) {
  std::string dir = argc > 1 ? argv[1] : "tests/vectors";
  auto load = [&](const char* name) { return mx::load(dir + "/" + name + ".npy"); };

  // Router parity.
  mx::array logits = load("router_logits");
  mx::array exp_inds = load("router_indices");
  mx::array exp_scores = load("router_scores");
  RouterOutput r = router(logits, 4, 0.0f);
  mx::eval(r.indices, r.scores);
  // Router indices are int32 on both sides.
  assert(bit_equal(r.indices, exp_inds) && "router indices differ");

  // MoE block parity. Load weights + inputs.
  mx::array x = load("x");
  mx::array route = load("route");
  mx::array scores = load("scores");
  mx::array gw = load("gw"), gs = load("gs"), gb = load("gb");
  mx::array uw = load("uw"), us = load("us"), ub = load("ub");
  mx::array dw = load("dw"), ds = load("ds"), db = load("db");
  mx::array expected = load("expected");
  ExpertWeights w(Q4Projection(gw, gs, gb), Q4Projection(uw, us, ub),
                  Q4Projection(dw, ds, db), 32, 4);
  mx::array out = moe_block(x, route, scores, w);
  mx::eval(out);

  if (!bit_equal(out, expected)) {
    // Report first difference for diagnosis.
    mx::array ov = mx::astype(mx::reshape(out, {-1}), mx::uint32);
    mx::array ev = mx::astype(mx::reshape(expected, {-1}), mx::uint32);
    mx::eval(ov, ev);
    size_t n = ov.size() < ev.size() ? ov.size() : ev.size();
    const uint32_t* a = ov.data<uint32_t>();
    const uint32_t* b = ev.data<uint32_t>();
    size_t diff = n;
    for (size_t i = 0; i < n; ++i)
      if (a[i] != b[i]) { diff = i; break; }
    std::fprintf(stderr,
                 "PARITY FAIL: shape out=%zu expected=%zu, first diff at %zu "
                 "(out=0x%08x expected=0x%08x)\n",
                 out.size(), expected.size(), diff,
                 diff < n ? a[diff] : 0, diff < n ? b[diff] : 0);
    return 1;
  }

  std::printf("test_engine_parity OK (router + moe_block bit-identical to Python)\n");
  return 0;
}
